(() => { const sel = "#banner", txt = "", ms = 3000;
  let els = [...document.querySelectorAll(sel)];
  if (txt) { els = els.filter((e) => (e.innerText || '').includes(txt));
             els = els.filter((e) => ![...e.children].some((c) => (c.innerText || '').includes(txt) && c.matches(sel))); }
  const el = els[0]; if (!el) throw new Error('highlight target not found: ' + sel + ' ' + txt);
  const r = el.getBoundingClientRect(), h = document.createElement('div');
  h.style.cssText = 'position:fixed;z-index:2147483646;pointer-events:none;border:3px solid #23E2C2;border-radius:10px;' +
    'box-shadow:0 0 0 9999px rgba(3,3,28,.2),0 0 22px rgba(35,226,194,.55);opacity:0;transition:opacity .4s ease;' +
    'left:' + (r.left - 7) + 'px;top:' + (r.top - 7) + 'px;width:' + (r.width + 14) + 'px;height:' + (r.height + 14) + 'px';
  document.body.appendChild(h); requestAnimationFrame(() => { h.style.opacity = 1; });
  setTimeout(() => { h.style.opacity = 0; }, ms - 450); setTimeout(() => h.remove(), ms); return 'highlight ' + (txt || sel); })()

